mapper.select:
SELECT COALESCE(SUM(i.count), 0)
FROM trade_order_item i
INNER JOIN trade_order o ON o.id = i.order_id AND o.deleted = 0
WHERE i.deleted = 0
  AND i.subscription_student_id = #{studentId}
  AND i.subscription_offer_sku_id = #{offerSkuId}
  AND o.status <> #{canceledStatus}

SELECT i.subscription_offer_sku_id AS offerSkuId,
       COALESCE(SUM(i.count), 0) AS quantity
FROM trade_order_item i
INNER JOIN trade_order o ON o.id = i.order_id AND o.deleted = 0
WHERE i.deleted = 0
  AND i.subscription_student_id = #{studentId}
  AND i.subscription_offer_sku_id IN

      #{offerSkuId}

  AND o.status <> #{canceledStatus}
GROUP BY i.subscription_offer_sku_id

SELECT i.sku_id AS skuId FROM trade_order_item i WHERE i.deleted = 0 AND i.subscription_offer_sku_id IS NOT NULL AND i.sku_id IN
#{productSkuId}
UNION SELECT pi.sku_id AS skuId FROM trade_order_publication_issue pi WHERE pi.deleted = 0 AND pi.sku_id IN
#{productSkuId}
